	if next.Code != http.StatusCreated {
		t.Fatalf("next status = %d: %s", next.Code, next.Body.String())
	}
	json.Unmarshal(next.Body.Bytes(), &body)
	if body["order"] != float64(2) {
		t.Fatalf("order after retry = %v, want 2", body["order"])
	}
}

