1	package api
2	
3	// System regression coverage for the closed-interval conflict rule published in
4	// README.md: a newly registered record is flagged only when an already committed
5	// record shares its namespace AND label, carries a rule with the same direction
6	// and the opposite action, and the two rules' closed port intervals share at
7	// least one port (intervals that merely touch at an endpoint overlap).
8	//
9	// These tests drive only the public POST/GET HTTP entries. The expected outcome
10	// for every case is computed by the small independent oracle below — written
11	// straight from the published rule — and never by the storage layer's own
12	// conflict function. Every failure message carries the input, the expectation
13	// and the actual response.
14	
15	import (
16		"encoding/json"
17		"fmt"
18		"net/http"
19		"reflect"
20		"testing"
21	
22		"github.com/gin-gonic/gin"
23	)
24	
25	// closedIntervalsSharePort is the oracle's independent reading of "closed
26	// intervals sharing at least one port": [a0,a1] and [b0,b1] intersect exactly
27	// when each starts at or before the other's end.
28	func closedIntervalsSharePort(a, b [2]int) bool {
29		return a[0] <= b[1] && b[0] <= a[1]
30	}
31	
32	// oracleRule describes one rule in the language of the published contract.
33	type oracleRule struct {
34		direction string
35		action    string
36		ports     [2]int
37	}
38	
39	// expectConflictAgainstHistory evaluates one candidate rule against every
40	// committed history rule using only the published conflict rule.
41	func expectConflictAgainstHistory(candidate oracleRule, history ...oracleRule) bool {
42		for _, older := range history {
43			if candidate.direction == older.direction &&
44				candidate.action != older.action &&
45				closedIntervalsSharePort(candidate.ports, older.ports) {
46				return true
47			}
48		}
49		return false
50	}
51	
52	// expectRulesConflict evaluates full rule lists: a record conflicts when any
53	// candidate rule clashes with any existing rule.
54	func expectRulesConflict(candidate, existing []oracleRule) bool {
55		for _, cand := range candidate {
56			for _, old := range existing {
57				if cand.direction == old.direction &&
58					cand.action != old.action &&
59					closedIntervalsSharePort(cand.ports, old.ports) {
60					return true
61				}
62			}
63		}
64		return false
65	}
66	
67	// postAndDecode runs a POST and decodes a record body when one is present. The
68	// input description is echoed in every failure message.
69	func postAndDecode(t *testing.T, router *gin.Engine, body, input string) (int, map[string]any) {
70		t.Helper()
71		recorder := doRequest(router, http.MethodPost, "/v1/net-policies", body)
72		var record map[string]any
73		if recorder.Code == http.StatusCreated || recorder.Code == http.StatusOK {
74			if err := json.Unmarshal(recorder.Body.Bytes(), &record); err != nil {
75				t.Fatalf("input %s: decode %d response %q: %v", input, recorder.Code, recorder.Body.String(), err)
76			}
77		}
78		return recorder.Code, record
79	}
80	
81	// mustCreated demands a 201 and verifies the complete response object against
82	// the submitted body plus the independently expected order and conflict flag.
83	func mustCreated(t *testing.T, router *gin.Engine, body, input string, order int64, conflict bool) map[string]any {
84		t.Helper()
85		status, record := postAndDecode(t, router, body, input)
86		if status != http.StatusCreated {
87			t.Fatalf("input %s: status = %d, want %d; body %s", input, status, http.StatusCreated, body)
88		}
89		want := wantRecord(t, body, order, conflict)
90		if !reflect.DeepEqual(record, want) {
91			t.Fatalf("input %s:\nrecord = %#v\n want  %#v", input, record, want)
92		}
93		return record
94	}
95	
96	// TestConflictMatrixClosedIntervalCombinations exhaustively compares every
97	// legal closed interval whose endpoints come from {1, 2, 3, 65534, 65535} — 15
98	// intervals, hence all 225 ordered interval pairs (each interval registered
99	// first as the old record and again as the new record, identity pairs included)
100	// — crossed with every legal direction/action combination on both sides (16),
101	// giving 3600 cases. The old record always lands in an empty history (201,
102	// conflict=false); the new record's flag must equal the independent oracle.
103	// Saved results are then read back through GET, and the whole set is executed a
104	// second time against a fresh store to prove repeatability.
105	func TestConflictMatrixClosedIntervalCombinations(t *testing.T) {
106		endpoints := []int{1, 2, 3, 65534, 65535}
107		var intervals [][2]int
108		for _, lo := range endpoints {
109			for _, hi := range endpoints {
110				if lo <= hi {
111					intervals = append(intervals, [2]int{lo, hi})
112				}
113			}
114		}
115		if len(intervals) != 15 {
116			t.Fatalf("legal intervals = %d, want 15 closed intervals from %v", len(intervals), endpoints)
117		}
118	
119		sides := []oracleRule{
120			{direction: "ingress", action: "allow"},
121			{direction: "ingress", action: "deny"},
122			{direction: "egress", action: "allow"},
123			{direction: "egress", action: "deny"},
124		}
125	
126		routerA, _ := newTestRouter(t)
127		routerB, _ := newTestRouter(t)
128	
129		var (
130			gotTrue, wantTrue   int
131			gotFalse, wantFalse int
132		)
133	
134		caseNo := 0
135		for _, seedPorts := range intervals {
136			for _, candPorts := range intervals {
137				for _, seedSide := range sides {
138					for _, candSide := range sides {
139						caseNo++
140						seed := oracleRule{direction: seedSide.direction, action: seedSide.action, ports: seedPorts}
141						cand := oracleRule{direction: candSide.direction, action: candSide.action, ports: candPorts}
142						wantConflict := expectConflictAgainstHistory(cand, seed)
143						if wantConflict {
144							wantTrue++
145						} else {
146							wantFalse++
147						}
148	
149						namespace := fmt.Sprintf("matrix-%04d", caseNo)
150						label := fmt.Sprintf("tier=matrix-%04d", caseNo)
151						input := fmt.Sprintf(
152							"seed={%s %s ports=[%d,%d]} candidate={%s %s ports=[%d,%d]} namespace=%s label=%s",
153							seed.direction, seed.action, seed.ports[0], seed.ports[1],
154							cand.direction, cand.action, cand.ports[0], cand.ports[1], namespace, label)
155						name := fmt.Sprintf("seed[%d,%d]%s/%s_cand[%d,%d]%s/%s",
156							seedPorts[0], seedPorts[1], seed.direction, seed.action,
157							candPorts[0], candPorts[1], candSide.direction, candSide.action)
158	
159						t.Run(name, func(t *testing.T) {
160							seedBody := singleRuleBody(namespace, "old", label,
161								seed.direction, seed.action, seed.ports[0], seed.ports[1], `{}`)
162							candBody := singleRuleBody(namespace, "new", label,
163								cand.direction, cand.action, cand.ports[0], cand.ports[1], `{}`)
164							seedOrder, candOrder := int64(2*caseNo-1), int64(2*caseNo)
165	
166							var saved [2]map[string]any
167							for run, router := range []*gin.Engine{routerA, routerB} {
168								// First registration in this namespace: 201, no history, no flag.
169								status, seedRecord := postAndDecode(t, router, seedBody, input+" run="+fmt.Sprint(run+1))
170								if status != http.StatusCreated {
171									t.Fatalf("input %s run %d: seed status = %d, want %d",
172										input, run+1, status, http.StatusCreated)
173								}
174								if wantSeed := wantRecord(t, seedBody, seedOrder, false); !reflect.DeepEqual(seedRecord, wantSeed) {
175									t.Fatalf("input %s run %d:\nseed record = %#v\n want       %#v",
176										input, run+1, seedRecord, wantSeed)
177								}
178	
179								status, candRecord := postAndDecode(t, router, candBody, input+" run="+fmt.Sprint(run+1))
180								if status != http.StatusCreated {
181									t.Fatalf("input %s run %d: candidate status = %d, want %d",
182										input, run+1, status, http.StatusCreated)
183								}
184								if conflict, _ := candRecord["conflict"].(bool); conflict != wantConflict {
185									t.Fatalf("input %s run %d: candidate conflict = %v, want %v\nrecord = %#v",
186										input, run+1, conflict, wantConflict, candRecord)
187								}
188								if wantCand := wantRecord(t, candBody, candOrder, wantConflict); !reflect.DeepEqual(candRecord, wantCand) {
189									t.Fatalf("input %s run %d:\ncandidate record = %#v\n want          %#v",
190										input, run+1, candRecord, wantCand)
191								}
192	
193								// Read the saved pair back: exact match, complete records,
194								// ascending by order.
195								items := listItems(t, router, "/v1/net-policies?namespace="+namespace)
196								if len(items) != 2 {
197									t.Fatalf("input %s run %d: GET returned %d items, want 2: %v",
198										input, run+1, len(items), items)
199								}
200								wantItems := []map[string]any{seedRecord, candRecord}
201								if !reflect.DeepEqual(items, wantItems) {
202									t.Fatalf("input %s run %d:\nsaved items = %#v\n want       %#v",
203										input, run+1, items, wantItems)
204								}
205								saved[run] = map[string]any{
206									"seed": seedRecord, "candidate": candRecord, "items": items,
207								}
208							}
209	
210							// Repeating the same set against a fresh store is identical.
211							if !reflect.DeepEqual(saved[0], saved[1]) {
212								t.Fatalf("input %s: repeated run diverged:\nfirst  = %#v\nsecond = %#v",
213									input, saved[0], saved[1])
214							}
215	
216							actual, _ := saved[0]["candidate"].(map[string]any)["conflict"].(bool)
217							if actual {
218								gotTrue++
219							} else {
220								gotFalse++
221							}
222						})
223					}
224				}
225			}
226		}
227	
228		// Aggregate guard on the wiring: actual true/false counts must match the
229		// oracle's counts, and both outcomes must actually have been exercised.
230		if gotTrue != wantTrue || gotFalse != wantFalse {
231			t.Fatalf("conflict tally = true %d/%d, false %d/%d (got/want)",
232				gotTrue, wantTrue, gotFalse, wantFalse)
233		}
234		if wantTrue == 0 || wantFalse == 0 {
235			t.Fatalf("oracle tally degenerate: true=%d false=%d", wantTrue, wantFalse)
236		}
237	
238		// Literal boundary pins derived directly from the published rule, guarding
239		// the generator and the oracle themselves: endpoint touching overlaps, the
240		// gap between 3 and 65534 does not, and the extreme ports overlap anything.
241		for _, tc := range []struct {
242			name                 string
243			seedPorts, candPorts [2]int
244			overlap              bool
245		}{
246			{"touch at endpoint 2", [2]int{1, 2}, [2]int{2, 3}, true},
247			{"touch at endpoint 3", [2]int{2, 3}, [2]int{3, 65534}, true},
248			{"touch at endpoint 65534", [2]int{3, 65534}, [2]int{65534, 65535}, true},
249			{"gap between 3 and 65534", [2]int{1, 3}, [2]int{65534, 65534}, false},
250			{"lower extreme 1", [2]int{1, 1}, [2]int{1, 65535}, true},
251			{"upper extreme 65535", [2]int{65535, 65535}, [2]int{1, 65535}, true},
252			{"same singleton interval", [2]int{65534, 65534}, [2]int{65534, 65534}, true},
253		} {
254			if got := closedIntervalsSharePort(tc.seedPorts, tc.candPorts); got != tc.overlap {
255				t.Fatalf("boundary pin %q: overlap = %v, want %v for %v and %v",
256					tc.name, got, tc.overlap, tc.seedPorts, tc.candPorts)
257			}
258		}
259	}
