491	// TestConflictRegressionRegistrationBoundaries pins the registration edges:
492	// 201 first time, 200 with the original on identical retry, 409 on changed rule
493	// order or a changed plugin string, 400 on out-of-range/inverted ports or an
494	// illegal direction. Rejected requests and retries neither add rows nor consume
495	// an order nor touch existing flags; the next legal record takes max order + 1.
496	func TestConflictRegressionRegistrationBoundaries(t *testing.T) {
497		router, _ := newTestRouter(t)
498	
499		seedBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
500			`{"mode": "enforce", "zone": "east"}`)
501		seed := mustCreated(t, router, seedBody, "first registration ingress deny [80,100]", 1, false)
502	
503		clashBody := singleRuleBody("payments", "clash", "tier=backend", "ingress", "allow", 100, 200,
504			`{"zone": "east"}`)
505		clash := mustCreated(t, router, clashBody, "second registration ingress allow [100,200]", 2, true)
506	
507		// Two egress rules (the history holds only ingress rules, so neither rule
508		// can clash); the two egress rules oppose each other on overlapping ports,
509		// which must not self-flag because conflict is only assessed against
510		// committed records.
511		orderedBody := policyWithRules("payments", "ordered", "tier=backend", `[
512			{"direction": "egress", "action": "deny",  "ports": [1, 100]},
513			{"direction": "egress", "action": "allow", "ports": [53, 53]}
514		]`, `{}`)
515		ordered := mustCreated(t, router, orderedBody, "two egress rules, history is ingress-only", 3, false)
516	
517		// Identical retry: 200 with the original record.
518		recorder := doRequest(router, http.MethodPost, "/v1/net-policies", clashBody)
519		if recorder.Code != http.StatusOK {
520			t.Fatalf("identical retry: status = %d, want %d; body %s",
521				recorder.Code, http.StatusOK, recorder.Body.String())
522		}
523		var retried map[string]any
524		if err := json.Unmarshal(recorder.Body.Bytes(), &retried); err != nil {
525			t.Fatalf("decode identical retry: %v", err)
526		}
527		if !reflect.DeepEqual(retried, clash) {
528			t.Fatalf("identical retry:\n got %#v\nwant original %#v", retried, clash)
529		}
530	
531		// Same content with pluginParams members reordered: still 200, same record.
532		reorderedParamsBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
533			`{"zone": "east", "mode": "enforce"}`)
534		recorder = doRequest(router, http.MethodPost, "/v1/net-policies", reorderedParamsBody)
535		if recorder.Code != http.StatusOK {
536			t.Fatalf("reordered-params retry: status = %d, want %d; body %s",
537				recorder.Code, http.StatusOK, recorder.Body.String())
538		}
539		if err := json.Unmarshal(recorder.Body.Bytes(), &retried); err != nil {
540			t.Fatalf("decode reordered retry: %v", err)
541		}
542		if !reflect.DeepEqual(retried, seed) {
543			t.Fatalf("reordered-params retry:\n got %#v\nwant original %#v", retried, seed)
544		}
545	
546		// Same identity, rules in a different order: 409.
547		swappedRulesBody := policyWithRules("payments", "ordered", "tier=backend", `[
548			{"direction": "egress", "action": "allow", "ports": [53, 53]},
549			{"direction": "egress", "action": "deny",  "ports": [1, 100]}
550		]`, `{}`)
551		recorder = doRequest(router, http.MethodPost, "/v1/net-policies", swappedRulesBody)
552		if recorder.Code != http.StatusConflict {
553			t.Fatalf("changed rule order: status = %d, want %d; body %s",
554				recorder.Code, http.StatusConflict, recorder.Body.String())
555		}
556		assertExactErrorShape(t, recorder, "NetPolicyConflictError")
557		assertSafeErrorMessage(t, recorder)
558	
559		// Same identity, a changed plugin string value: 409.
560		changedParamBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
561			`{"mode": "audit", "zone": "east"}`)
562		recorder = doRequest(router, http.MethodPost, "/v1/net-policies", changedParamBody)
563		if recorder.Code != http.StatusConflict {
564			t.Fatalf("changed plugin value: status = %d, want %d; body %s",
565				recorder.Code, http.StatusConflict, recorder.Body.String())
566		}
567		assertExactErrorShape(t, recorder, "NetPolicyConflictError")
568		assertSafeErrorMessage(t, recorder)
569	
570		// Invalid input on fresh identities: 400, published error envelope.
571		invalidCases := []struct {
572			name string
573			body string
574		}{
575			{"port zero", singleRuleBody("payments", "bad-zero", "tier=backend", "ingress", "allow", 0, 80, `{}`)},
576			{"port above 65535", singleRuleBody("payments", "bad-high", "tier=backend", "ingress", "allow", 1, 65536, `{}`)},
577			{"inverted interval", policyWithRules("payments", "bad-inverted", "tier=backend",
578				`[{"direction": "ingress", "action": "allow", "ports": [443, 80]}]`, `{}`)},
579			{"illegal direction", singleRuleBody("payments", "bad-direction", "tier=backend", "sideways", "allow", 80, 80, `{}`)},
580		}
581		for _, tc := range invalidCases {
582			t.Run(tc.name, func(t *testing.T) {
583				recorder := doRequest(router, http.MethodPost, "/v1/net-policies", tc.body)
584				if recorder.Code != http.StatusBadRequest {
585					t.Fatalf("input %s: status = %d, want %d; body %s",
586						tc.body, recorder.Code, http.StatusBadRequest, recorder.Body.String())
587				}
588				assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
589				assertSafeErrorMessage(t, recorder)
590			})
591		}
592	
593		// Nothing was added and no committed field, order or flag changed.
594		items := listItems(t, router, "/v1/net-policies?namespace=payments")
595		if want := []map[string]any{seed, clash, ordered}; !reflect.DeepEqual(items, want) {
596			t.Fatalf("registry after rejects/retries:\nitems = %#v\n want %#v", items, want)
597		}
598	
599		// The next legal new identity continues at the current maximum order + 1.
600		// ingress deny [300,400] is disjoint from the ingress allow [100,200]
601		// history rule and shares an action with ingress deny [80,100], so it must
602		// land conflict-free.
603		nextBody := singleRuleBody("payments", "after-boundaries", "tier=backend", "ingress", "deny", 300, 400, `{}`)
604		next := mustCreated(t, router, nextBody, "legal ingress deny [300,400] after all rejected attempts", 4, false)
605		if next["order"] != float64(4) {
606			t.Fatalf("next record order = %v, want 4 (rejects and retries must not consume an order)", next["order"])
607		}
608	}
609

