package api

// System regression coverage for the closed-interval conflict rule published in
// README.md: a newly registered record is flagged only when an already committed
// record shares its namespace AND label, carries a rule with the same direction
// and the opposite action, and the two rules' closed port intervals share at
// least one port (intervals that merely touch at an endpoint overlap).
//
// These tests drive only the public POST/GET HTTP entries. The expected outcome
// for every case is computed by the small independent oracle below — written
// straight from the published rule — and never by the storage layer's own
// conflict function. Every failure message carries the input, the expectation
// and the actual response.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"reflect"
	"testing"

	"github.com/gin-gonic/gin"
)

// closedIntervalsSharePort is the oracle's independent reading of "closed
// intervals sharing at least one port": [a0,a1] and [b0,b1] intersect exactly
// when each starts at or before the other's end.
func closedIntervalsSharePort(a, b [2]int) bool {
	return a[0] <= b[1] && b[0] <= a[1]
}

// oracleRule describes one rule in the language of the published contract.
type oracleRule struct {
	direction string
	action    string
	ports     [2]int
}

// expectConflictAgainstHistory evaluates one candidate rule against every
// committed history rule using only the published conflict rule.
func expectConflictAgainstHistory(candidate oracleRule, history ...oracleRule) bool {
	for _, older := range history {
		if candidate.direction == older.direction &&
			candidate.action != older.action &&
			closedIntervalsSharePort(candidate.ports, older.ports) {
			return true
		}
	}
	return false
}

// expectRulesConflict evaluates full rule lists: a record conflicts when any
// candidate rule clashes with any existing rule.
func expectRulesConflict(candidate, existing []oracleRule) bool {
	for _, cand := range candidate {
		for _, old := range existing {
			if cand.direction == old.direction &&
				cand.action != old.action &&
				closedIntervalsSharePort(cand.ports, old.ports) {
				return true
			}
		}
	}
	return false
}

// postAndDecode runs a POST and decodes a record body when one is present. The
// input description is echoed in every failure message.
func postAndDecode(t *testing.T, router *gin.Engine, body, input string) (int, map[string]any) {
	t.Helper()
	recorder := doRequest(router, http.MethodPost, "/v1/net-policies", body)
	var record map[string]any
	if recorder.Code == http.StatusCreated || recorder.Code == http.StatusOK {
		if err := json.Unmarshal(recorder.Body.Bytes(), &record); err != nil {
			t.Fatalf("input %s: decode %d response %q: %v", input, recorder.Code, recorder.Body.String(), err)
		}
	}
	return recorder.Code, record
}

// mustCreated demands a 201 and verifies the complete response object against
// the submitted body plus the independently expected order and conflict flag.
func mustCreated(t *testing.T, router *gin.Engine, body, input string, order int64, conflict bool) map[string]any {
	t.Helper()
	status, record := postAndDecode(t, router, body, input)
	if status != http.StatusCreated {
		t.Fatalf("input %s: status = %d, want %d; body %s", input, status, http.StatusCreated, body)
	}
	want := wantRecord(t, body, order, conflict)
	if !reflect.DeepEqual(record, want) {
		t.Fatalf("input %s:\nrecord = %#v\n want  %#v", input, record, want)
	}
	return record
}

// TestConflictMatrixClosedIntervalCombinations exhaustively compares every
// legal closed interval whose endpoints come from {1, 2, 3, 65534, 65535} — 15
// intervals, hence all 225 ordered interval pairs (each interval registered
// first as the old record and again as the new record, identity pairs included)
// — crossed with every legal direction/action combination on both sides (16),
// giving 3600 cases. The old record always lands in an empty history (201,
// conflict=false); the new record's flag must equal the independent oracle.
// Saved results are then read back through GET, and the whole set is executed a
// second time against a fresh store to prove repeatability.
func TestConflictMatrixClosedIntervalCombinations(t *testing.T) {
	endpoints := []int{1, 2, 3, 65534, 65535}
	var intervals [][2]int
	for _, lo := range endpoints {
		for _, hi := range endpoints {
			if lo <= hi {
				intervals = append(intervals, [2]int{lo, hi})
			}
		}
	}
	if len(intervals) != 15 {
		t.Fatalf("legal intervals = %d, want 15 closed intervals from %v", len(intervals), endpoints)
	}

	sides := []oracleRule{
		{direction: "ingress", action: "allow"},
		{direction: "ingress", action: "deny"},
		{direction: "egress", action: "allow"},
		{direction: "egress", action: "deny"},
	}

	routerA, _ := newTestRouter(t)
	routerB, _ := newTestRouter(t)

	var (
		gotTrue, wantTrue   int
		gotFalse, wantFalse int
	)

	caseNo := 0
	for _, seedPorts := range intervals {
		for _, candPorts := range intervals {
			for _, seedSide := range sides {
				for _, candSide := range sides {
					caseNo++
					seed := oracleRule{direction: seedSide.direction, action: seedSide.action, ports: seedPorts}
					cand := oracleRule{direction: candSide.direction, action: candSide.action, ports: candPorts}
					wantConflict := expectConflictAgainstHistory(cand, seed)
					if wantConflict {
						wantTrue++
					} else {
						wantFalse++
					}

					namespace := fmt.Sprintf("matrix-%04d", caseNo)
					label := fmt.Sprintf("tier=matrix-%04d", caseNo)
					input := fmt.Sprintf(
						"seed={%s %s ports=[%d,%d]} candidate={%s %s ports=[%d,%d]} namespace=%s label=%s",
						seed.direction, seed.action, seed.ports[0], seed.ports[1],
						cand.direction, cand.action, cand.ports[0], cand.ports[1], namespace, label)
					name := fmt.Sprintf("seed[%d,%d]%s/%s_cand[%d,%d]%s/%s",
						seedPorts[0], seedPorts[1], seed.direction, seed.action,
						candPorts[0], candPorts[1], candSide.direction, candSide.action)

					t.Run(name, func(t *testing.T) {
						seedBody := singleRuleBody(namespace, "old", label,
							seed.direction, seed.action, seed.ports[0], seed.ports[1], `{}`)
						candBody := singleRuleBody(namespace, "new", label,
							cand.direction, cand.action, cand.ports[0], cand.ports[1], `{}`)
						seedOrder, candOrder := int64(2*caseNo-1), int64(2*caseNo)

						var saved [2]map[string]any
						for run, router := range []*gin.Engine{routerA, routerB} {
							// First registration in this namespace: 201, no history, no flag.
							status, seedRecord := postAndDecode(t, router, seedBody, input+" run="+fmt.Sprint(run+1))
							if status != http.StatusCreated {
								t.Fatalf("input %s run %d: seed status = %d, want %d",
									input, run+1, status, http.StatusCreated)
							}
							if wantSeed := wantRecord(t, seedBody, seedOrder, false); !reflect.DeepEqual(seedRecord, wantSeed) {
								t.Fatalf("input %s run %d:\nseed record = %#v\n want       %#v",
									input, run+1, seedRecord, wantSeed)
							}

							status, candRecord := postAndDecode(t, router, candBody, input+" run="+fmt.Sprint(run+1))
							if status != http.StatusCreated {
								t.Fatalf("input %s run %d: candidate status = %d, want %d",
									input, run+1, status, http.StatusCreated)
							}
							if conflict, _ := candRecord["conflict"].(bool); conflict != wantConflict {
								t.Fatalf("input %s run %d: candidate conflict = %v, want %v\nrecord = %#v",
									input, run+1, conflict, wantConflict, candRecord)
							}
							if wantCand := wantRecord(t, candBody, candOrder, wantConflict); !reflect.DeepEqual(candRecord, wantCand) {
								t.Fatalf("input %s run %d:\ncandidate record = %#v\n want          %#v",
									input, run+1, candRecord, wantCand)
							}

							// Read the saved pair back: exact match, complete records,
							// ascending by order.
							items := listItems(t, router, "/v1/net-policies?namespace="+namespace)
							if len(items) != 2 {
								t.Fatalf("input %s run %d: GET returned %d items, want 2: %v",
									input, run+1, len(items), items)
							}
							wantItems := []map[string]any{seedRecord, candRecord}
							if !reflect.DeepEqual(items, wantItems) {
								t.Fatalf("input %s run %d:\nsaved items = %#v\n want       %#v",
									input, run+1, items, wantItems)
							}
							saved[run] = map[string]any{
								"seed": seedRecord, "candidate": candRecord, "items": items,
							}
						}

						// Repeating the same set against a fresh store is identical.
						if !reflect.DeepEqual(saved[0], saved[1]) {
							t.Fatalf("input %s: repeated run diverged:\nfirst  = %#v\nsecond = %#v",
								input, saved[0], saved[1])
						}

						actual, _ := saved[0]["candidate"].(map[string]any)["conflict"].(bool)
						if actual {
							gotTrue++
						} else {
							gotFalse++
						}
					})
				}
			}
		}
	}

	// Aggregate guard on the wiring: actual true/false counts must match the
	// oracle's counts, and both outcomes must actually have been exercised.
	if gotTrue != wantTrue || gotFalse != wantFalse {
		t.Fatalf("conflict tally = true %d/%d, false %d/%d (got/want)",
			gotTrue, wantTrue, gotFalse, wantFalse)
	}
	if wantTrue == 0 || wantFalse == 0 {
		t.Fatalf("oracle tally degenerate: true=%d false=%d", wantTrue, wantFalse)
	}

	// Literal boundary pins derived directly from the published rule, guarding
	// the generator and the oracle themselves: endpoint touching overlaps, the
	// gap between 3 and 65534 does not, and the extreme ports overlap anything.
	for _, tc := range []struct {
		name                 string
		seedPorts, candPorts [2]int
		overlap              bool
	}{
		{"touch at endpoint 2", [2]int{1, 2}, [2]int{2, 3}, true},
		{"touch at endpoint 3", [2]int{2, 3}, [2]int{3, 65534}, true},
		{"touch at endpoint 65534", [2]int{3, 65534}, [2]int{65534, 65535}, true},
		{"gap between 3 and 65534", [2]int{1, 3}, [2]int{65534, 65534}, false},
		{"lower extreme 1", [2]int{1, 1}, [2]int{1, 65535}, true},
		{"upper extreme 65535", [2]int{65535, 65535}, [2]int{1, 65535}, true},
		{"same singleton interval", [2]int{65534, 65534}, [2]int{65534, 65534}, true},
	} {
		if got := closedIntervalsSharePort(tc.seedPorts, tc.candPorts); got != tc.overlap {
			t.Fatalf("boundary pin %q: overlap = %v, want %v for %v and %v",
				tc.name, got, tc.overlap, tc.seedPorts, tc.candPorts)
		}
	}
}

// TestConflictRegressionMultipleHistoryRecords covers a history longer than
// one record: a candidate that clashes only with an EARLIER record (not the
// newest one) is still flagged, and every older record keeps its content, order
// and conflict flag afterwards.
func TestConflictRegressionMultipleHistoryRecords(t *testing.T) {
	router, _ := newTestRouter(t)

	earlyBody := singleRuleBody("payments", "early", "tier=backend", "ingress", "deny", 80, 100, `{}`)
	early := mustCreated(t, router, earlyBody, "early ingress deny [80,100]", 1, false)

	latestBody := singleRuleBody("payments", "latest", "tier=backend", "ingress", "allow", 300, 400, `{}`)
	// Opposite action from early but the intervals are disjoint: no conflict.
	latest := mustCreated(t, router, latestBody, "latest ingress allow [300,400]", 2,
		expectConflictAgainstHistory(
			oracleRule{"ingress", "allow", [2]int{300, 400}},
			oracleRule{"ingress", "deny", [2]int{80, 100}}))

	// Allow [90,90]: same action as the newest record (no clash there) but
	// opposite action and overlapping ports against the EARLIER record.
	candHistory := []oracleRule{
		{direction: "ingress", action: "deny", ports: [2]int{80, 100}},
		{direction: "ingress", action: "allow", ports: [2]int{300, 400}},
	}
	candBody := singleRuleBody("payments", "candidate", "tier=backend", "ingress", "allow", 90, 90, `{}`)
	wantConflict := expectConflictAgainstHistory(oracleRule{"ingress", "allow", [2]int{90, 90}}, candHistory...)
	if !wantConflict {
		t.Fatalf("oracle setup wrong: candidate against early deny [80,100] must conflict")
	}
	cand := mustCreated(t, router, candBody, "candidate ingress allow [90,90]", 3, true)

	items := listItems(t, router, "/v1/net-policies?namespace=payments")
	wantItems := []map[string]any{early, latest, cand}
	if !reflect.DeepEqual(items, wantItems) {
		t.Fatalf("after candidate registration:\nitems = %#v\n want %#v", items, wantItems)
	}
}

// TestConflictRegressionClashOnlyOnLastRules builds multi-rule records where the
// ONLY clashing rule pair is the last rule of each side; all preceding rule
// pairs differ in direction, share an action, or have disjoint ports.
func TestConflictRegressionClashOnlyOnLastRules(t *testing.T) {
	router, _ := newTestRouter(t)

	seedBody := policyWithRules("multi", "seed", "tier=backend", `[
		{"direction": "egress",  "action": "allow", "ports": [53, 53]},
		{"direction": "egress",  "action": "deny",  "ports": [8000, 9000]},
		{"direction": "ingress", "action": "deny",  "ports": [80, 100]}
	]`, `{"zone": "east"}`)
	seedSpecs := []oracleRule{
		{direction: "egress", action: "allow", ports: [2]int{53, 53}},
		{direction: "egress", action: "deny", ports: [2]int{8000, 9000}},
		{direction: "ingress", action: "deny", ports: [2]int{80, 100}},
	}
	seed := mustCreated(t, router, seedBody, "seed 3 rules ending ingress deny [80,100]", 1, false)

	candBody := policyWithRules("multi", "candidate", "tier=backend", `[
		{"direction": "egress",  "action": "deny",  "ports": [6000, 7000]},
		{"direction": "ingress", "action": "allow", "ports": [90, 90]}
	]`, `{"zone": "west"}`)
	candSpecs := []oracleRule{
		{direction: "egress", action: "deny", ports: [2]int{6000, 7000}},
		{direction: "ingress", action: "allow", ports: [2]int{90, 90}},
	}
	wantConflict := expectRulesConflict(candSpecs, seedSpecs)
	if !wantConflict {
		t.Fatalf("oracle setup wrong: last rules ingress deny [80,100] vs ingress allow [90,90] must conflict")
	}
	cand := mustCreated(t, router, candBody, "candidate last rule ingress allow [90,90]", 2, true)

	items := listItems(t, router, "/v1/net-policies?namespace=multi")
	if want := []map[string]any{seed, cand}; !reflect.DeepEqual(items, want) {
		t.Fatalf("last-rule-clash items = %#v, want %#v", items, want)
	}
}

// TestConflictRegressionNoSelfConflictInsideFirstRecord registers ONE record
// whose own rules oppose each other on overlapping ports: with no history there
// is nothing to conflict with, so the flag must be false.
func TestConflictRegressionNoSelfConflictInsideFirstRecord(t *testing.T) {
	router, _ := newTestRouter(t)

	body := policyWithRules("self", "split", "tier=backend", `[
		{"direction": "ingress", "action": "deny",  "ports": [80, 100]},
		{"direction": "ingress", "action": "allow", "ports": [90, 90]},
		{"direction": "egress",  "action": "allow", "ports": [80, 100]}
	]`, `{"mode": "enforce"}`)
	record := mustCreated(t, router, body,
		"single record containing ingress deny [80,100] and ingress allow [90,90]", 1, false)

	items := listItems(t, router, "/v1/net-policies?namespace=self")
	if !reflect.DeepEqual(items, []map[string]any{record}) {
		t.Fatalf("self-conflicting record stored as %#v, want %#v", items, record)
	}
}

// TestConflictRegressionNamespaceAndLabelIsolation changes namespace and label
// one dimension at a time; conflict detection requires BOTH to match.
func TestConflictRegressionNamespaceAndLabelIsolation(t *testing.T) {
	router, _ := newTestRouter(t)

	seedBody := singleRuleBody("iso", "seed", "tier=backend", "ingress", "deny", 80, 100, `{}`)
	seed := mustCreated(t, router, seedBody, "iso/tier=backend ingress deny [80,100]", 1, false)

	// Different namespace, same label and a rule that WOULD clash by the
	// rule-level oracle: namespace isolation must suppress the flag.
	wouldClashAcrossNamespace := expectConflictAgainstHistory(
		oracleRule{"ingress", "allow", [2]int{90, 90}},
		oracleRule{"ingress", "deny", [2]int{80, 100}})
	if !wouldClashAcrossNamespace {
		t.Fatalf("oracle setup wrong: ingress allow [90,90] vs ingress deny [80,100] clash by rules")
	}
	otherNsBody := singleRuleBody("other-ns", "seed", "tier=backend", "ingress", "allow", 90, 90, `{}`)
	otherNs := mustCreated(t, router, otherNsBody,
		"namespace=other-ns label=tier=backend ingress allow [90,90]", 2, false)

	// Same namespace, different label, same rule-level clash: label isolation
	// must suppress the flag just as well.
	otherLabelBody := singleRuleBody("iso", "frontend", "tier=frontend", "ingress", "allow", 90, 90, `{}`)
	otherLabel := mustCreated(t, router, otherLabelBody,
		"namespace=iso label=tier=frontend ingress allow [90,90]", 3, false)

	// Control: same namespace AND same label with a clashing rule is flagged.
	controlBody := singleRuleBody("iso", "control", "tier=backend", "ingress", "allow", 90, 90, `{}`)
	control := mustCreated(t, router, controlBody,
		"namespace=iso label=tier=backend ingress allow [90,90]", 4, true)

	// The seed must be untouched after the later flagged registration.
	items := listItems(t, router, "/v1/net-policies?namespace=iso&label=tier%3Dbackend")
	if want := []map[string]any{seed, control}; !reflect.DeepEqual(items, want) {
		t.Fatalf("isolated query items = %#v, want %#v (seed conflict/order/content unchanged)", items, want)
	}
	if got := listItems(t, router, "/v1/net-policies?namespace=other-ns"); !reflect.DeepEqual(got, []map[string]any{otherNs}) {
		t.Fatalf("other-namespace items = %#v, want %#v", got, []map[string]any{otherNs})
	}
	if got := listItems(t, router, "/v1/net-policies?namespace=iso&label=tier%3Dfrontend"); !reflect.DeepEqual(got, []map[string]any{otherLabel}) {
		t.Fatalf("other-label items = %#v, want %#v", got, []map[string]any{otherLabel})
	}
}

// TestConflictRegressionPluginParamsDoNotAffectDecision verifies that differing
// pluginParams neither create nor suppress a conflict: the flag follows the
// rules only.
func TestConflictRegressionPluginParamsDoNotAffectDecision(t *testing.T) {
	router, _ := newTestRouter(t)

	seedBody := singleRuleBody("plug", "seed", "tier=backend", "ingress", "deny", 80, 100,
		`{"mode": "enforce", "zone": "east"}`)
	seed := mustCreated(t, router, seedBody, `seed params {"mode":"enforce","zone":"east"}`, 1, false)

	// Touching intervals, opposite action, but a different plugin string value:
	// still a conflict.
	clashBody := singleRuleBody("plug", "clash", "tier=backend", "ingress", "allow", 100, 200,
		`{"mode": "audit"}`)
	clash := mustCreated(t, router, clashBody, `clash params {"mode":"audit"}`, 2, true)

	// Disjoint intervals with yet different params: still no conflict.
	disjointBody := singleRuleBody("plug", "disjoint", "tier=backend", "ingress", "allow", 300, 400,
		`{"mode": "inspect", "retries": "9"}`)
	disjoint := mustCreated(t, router, disjointBody,
		`disjoint params {"mode":"inspect","retries":"9"}`, 3, false)

	items := listItems(t, router, "/v1/net-policies?namespace=plug")
	if want := []map[string]any{seed, clash, disjoint}; !reflect.DeepEqual(items, want) {
		t.Fatalf("plugin-param items = %#v, want %#v", items, want)
	}
}

// TestConflictRegressionQueriesMatchExactly verifies namespace, label and
// intersection queries return complete records in ascending order, that a
// miss is 404 NetPolicyNotFoundError, and that adding a flagged record leaves
// the older record's content, order and conflict flag unchanged.
func TestConflictRegressionQueriesMatchExactly(t *testing.T) {
	router, _ := newTestRouter(t)

	r1Body := singleRuleBody("payments", "p1", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "enforce"}`)
	r1 := mustCreated(t, router, r1Body, "payments/p1 tier=backend", 1, false)
	r2Body := singleRuleBody("payments", "p2", "tier=backend", "ingress", "allow", 100, 200, `{"zone": "east"}`)
	r2 := mustCreated(t, router, r2Body, "payments/p2 tier=backend (touch at 100)", 2, true)
	r3Body := singleRuleBody("payments", "p3", "tier=frontend", "egress", "allow", 53, 53, `{}`)
	r3 := mustCreated(t, router, r3Body, "payments/p3 tier=frontend", 3, false)
	r4Body := singleRuleBody("staging", "p4", "tier=backend", "ingress", "allow", 80, 80, `{}`)
	r4 := mustCreated(t, router, r4Body, "staging/p4 tier=backend (different namespace)", 4, false)

	for _, tc := range []struct {
		name   string
		target string
		want   []map[string]any
	}{
		{"namespace", "/v1/net-policies?namespace=payments", []map[string]any{r1, r2, r3}},
		{"label across namespaces", "/v1/net-policies?label=tier%3Dbackend", []map[string]any{r1, r2, r4}},
		{"intersection", "/v1/net-policies?namespace=payments&label=tier%3Dbackend", []map[string]any{r1, r2}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			items := listItems(t, router, tc.target)
			if !reflect.DeepEqual(items, tc.want) {
				t.Fatalf("GET %s:\nitems = %#v\n want %#v", tc.target, items, tc.want)
			}
			var prev int64
			for i, item := range items {
				order, _ := item["order"].(float64)
				if int64(order) <= prev && i > 0 {
					t.Fatalf("GET %s items not ascending by order: %#v", tc.target, items)
				}
				prev = int64(order)
			}
		})
	}

	// The older record stays exactly as first registered after the clash.
	items := listItems(t, router, "/v1/net-policies?namespace=payments&label=tier%3Dbackend")
	if !reflect.DeepEqual(items[0], r1) {
		t.Fatalf("older record changed after new registration:\n got %#v\nwant %#v", items[0], r1)
	}

	for _, target := range []string{
		"/v1/net-policies?namespace=missing",
		"/v1/net-policies?label=tier%3Dmissing",
		"/v1/net-policies?namespace=payments&label=tier%3Dmissing",
		"/v1/net-policies?namespace=staging&label=tier%3Dfrontend",
	} {
		recorder := doRequest(router, http.MethodGet, target, "")
		if recorder.Code != http.StatusNotFound {
			t.Fatalf("GET %s: status = %d, want %d; body %s",
				target, recorder.Code, http.StatusNotFound, recorder.Body.String())
		}
		assertExactErrorShape(t, recorder, "NetPolicyNotFoundError")
		assertSafeErrorMessage(t, recorder)
	}
}

// TestConflictRegressionRegistrationBoundaries pins the registration edges:
// 201 first time, 200 with the original on identical retry, 409 on changed rule
// order or a changed plugin string, 400 on out-of-range/inverted ports or an
// illegal direction. Rejected requests and retries neither add rows nor consume
// an order nor touch existing flags; the next legal record takes max order + 1.
func TestConflictRegressionRegistrationBoundaries(t *testing.T) {
	router, _ := newTestRouter(t)

	seedBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
		`{"mode": "enforce", "zone": "east"}`)
	seed := mustCreated(t, router, seedBody, "first registration ingress deny [80,100]", 1, false)

	clashBody := singleRuleBody("payments", "clash", "tier=backend", "ingress", "allow", 100, 200,
		`{"zone": "east"}`)
	clash := mustCreated(t, router, clashBody, "second registration ingress allow [100,200]", 2, true)

	// Two egress rules (the history holds only ingress rules, so neither rule
	// can clash); the two egress rules oppose each other on overlapping ports,
	// which must not self-flag because conflict is only assessed against
	// committed records.
	orderedBody := policyWithRules("payments", "ordered", "tier=backend", `[
		{"direction": "egress", "action": "deny",  "ports": [1, 100]},
		{"direction": "egress", "action": "allow", "ports": [53, 53]}
	]`, `{}`)
	ordered := mustCreated(t, router, orderedBody, "two egress rules, history is ingress-only", 3, false)

	// Identical retry: 200 with the original record.
	recorder := doRequest(router, http.MethodPost, "/v1/net-policies", clashBody)
	if recorder.Code != http.StatusOK {
		t.Fatalf("identical retry: status = %d, want %d; body %s",
			recorder.Code, http.StatusOK, recorder.Body.String())
	}
	var retried map[string]any
	if err := json.Unmarshal(recorder.Body.Bytes(), &retried); err != nil {
		t.Fatalf("decode identical retry: %v", err)
	}
	if !reflect.DeepEqual(retried, clash) {
		t.Fatalf("identical retry:\n got %#v\nwant original %#v", retried, clash)
	}

	// Same content with pluginParams members reordered: still 200, same record.
	reorderedParamsBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
		`{"zone": "east", "mode": "enforce"}`)
	recorder = doRequest(router, http.MethodPost, "/v1/net-policies", reorderedParamsBody)
	if recorder.Code != http.StatusOK {
		t.Fatalf("reordered-params retry: status = %d, want %d; body %s",
			recorder.Code, http.StatusOK, recorder.Body.String())
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &retried); err != nil {
		t.Fatalf("decode reordered retry: %v", err)
	}
	if !reflect.DeepEqual(retried, seed) {
		t.Fatalf("reordered-params retry:\n got %#v\nwant original %#v", retried, seed)
	}

	// Same identity, rules in a different order: 409.
	swappedRulesBody := policyWithRules("payments", "ordered", "tier=backend", `[
		{"direction": "egress", "action": "allow", "ports": [53, 53]},
		{"direction": "egress", "action": "deny",  "ports": [1, 100]}
	]`, `{}`)
	recorder = doRequest(router, http.MethodPost, "/v1/net-policies", swappedRulesBody)
	if recorder.Code != http.StatusConflict {
		t.Fatalf("changed rule order: status = %d, want %d; body %s",
			recorder.Code, http.StatusConflict, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "NetPolicyConflictError")
	assertSafeErrorMessage(t, recorder)

	// Same identity, a changed plugin string value: 409.
	changedParamBody := singleRuleBody("payments", "seed", "tier=backend", "ingress", "deny", 80, 100,
		`{"mode": "audit", "zone": "east"}`)
	recorder = doRequest(router, http.MethodPost, "/v1/net-policies", changedParamBody)
	if recorder.Code != http.StatusConflict {
		t.Fatalf("changed plugin value: status = %d, want %d; body %s",
			recorder.Code, http.StatusConflict, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "NetPolicyConflictError")
	assertSafeErrorMessage(t, recorder)

	// Invalid input on fresh identities: 400, published error envelope.
	invalidCases := []struct {
		name string
		body string
	}{
		{"port zero", singleRuleBody("payments", "bad-zero", "tier=backend", "ingress", "allow", 0, 80, `{}`)},
		{"port above 65535", singleRuleBody("payments", "bad-high", "tier=backend", "ingress", "allow", 1, 65536, `{}`)},
		{"inverted interval", policyWithRules("payments", "bad-inverted", "tier=backend",
			`[{"direction": "ingress", "action": "allow", "ports": [443, 80]}]`, `{}`)},
		{"illegal direction", singleRuleBody("payments", "bad-direction", "tier=backend", "sideways", "allow", 80, 80, `{}`)},
	}
	for _, tc := range invalidCases {
		t.Run(tc.name, func(t *testing.T) {
			recorder := doRequest(router, http.MethodPost, "/v1/net-policies", tc.body)
			if recorder.Code != http.StatusBadRequest {
				t.Fatalf("input %s: status = %d, want %d; body %s",
					tc.body, recorder.Code, http.StatusBadRequest, recorder.Body.String())
			}
			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
			assertSafeErrorMessage(t, recorder)
		})
	}

	// Nothing was added and no committed field, order or flag changed.
	items := listItems(t, router, "/v1/net-policies?namespace=payments")
	if want := []map[string]any{seed, clash, ordered}; !reflect.DeepEqual(items, want) {
		t.Fatalf("registry after rejects/retries:\nitems = %#v\n want %#v", items, want)
	}

	// The next legal new identity continues at the current maximum order + 1.
	// ingress deny [300,400] is disjoint from the ingress allow [100,200]
	// history rule and shares an action with ingress deny [80,100], so it must
	// land conflict-free.
	nextBody := singleRuleBody("payments", "after-boundaries", "tier=backend", "ingress", "deny", 300, 400, `{}`)
	next := mustCreated(t, router, nextBody, "legal ingress deny [300,400] after all rejected attempts", 4, false)
	if next["order"] != float64(4) {
		t.Fatalf("next record order = %v, want 4 (rejects and retries must not consume an order)", next["order"])
	}
}

package api

// Strict query parsing regression tests for GET /v1/net-policies: the whole
// query string must validate before any record is returned, legal encodings
// keep the original matching semantics, and queries never mutate the registry.

import (
	"net/http"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
)

// A malformed fragment rejects the whole query no matter where it sits —
// first, middle or last segment, in a name or a value, in a known or an
// unknown parameter — and no matter whether the remaining conditions would
// have matched committed records. The committed records, their order and
// their conflict flags stay untouched.
func TestGetNetPoliciesRejectsMalformedQuerySegments(t *testing.T) {
	router, _ := newTestRouter(t)
	deny := registerCreated(t, router,
		singleRuleBody("payments", "default-deny", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "enforce"}`),
		1, false)
	allow := registerCreated(t, router,
		singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200, `{"mode": "enforce"}`),
		2, true)

	cases := map[string]string{
		// The headline case: a matching record exists, yet the bad escape
		// in the repeated parameter must not return it.
		"bad escape after matching namespace": "/v1/net-policies?namespace=payments&namespace=%ZZ",
		"bad escape in first segment":         "/v1/net-policies?namespace=%ZZ&namespace=payments",
		"bad escape in middle segment":        "/v1/net-policies?namespace=payments&junk=%2&label=tier%3Dbackend",
		"bad escape in last segment":          "/v1/net-policies?namespace=payments&junk=%",
		"incomplete escape at end of value":   "/v1/net-policies?namespace=paymen%7",
		"lone percent in value":               "/v1/net-policies?namespace=pay%ments",
		"non-hex escape in value":             "/v1/net-policies?namespace=pay%GGments",
		"bad escape in unknown param name":    "/v1/net-policies?%ZZ=x&namespace=payments",
		"bad escape in unknown param value":   "/v1/net-policies?junk=%ZZ&namespace=payments",
		"bad escape with non-matching filter": "/v1/net-policies?namespace=missing&junk=%ZZ",
		"semicolon in value":                  "/v1/net-policies?namespace=payments;extra",
		"semicolon in unknown param":          "/v1/net-policies?namespace=payments&junk=a;b",
		"semicolon in name":                   "/v1/net-policies?name;space=payments",
		"semicolon only segment":              "/v1/net-policies?namespace=payments&;",
		"duplicate identical value":           "/v1/net-policies?namespace=payments&namespace=payments",
		"duplicate via encoded name":          "/v1/net-policies?namespace=payments&%6Eamespace=payments",
		"duplicate label identical value":     "/v1/net-policies?label=tier%3Dbackend&label=tier%3Dbackend",
		"empty value":                         "/v1/net-policies?namespace=",
		"whitespace value from plus":          "/v1/net-policies?namespace=+",
		"whitespace value from escape":        "/v1/net-policies?namespace=%20",
		"no condition, only unknown param":    "/v1/net-policies?junk=x",
	}
	for name, target := range cases {
		t.Run(name, func(t *testing.T) {
			recorder := doRequest(router, http.MethodGet, target, "")
			if recorder.Code != http.StatusBadRequest {
				t.Fatalf("GET %s status = %d, want %d: %s",
					target, recorder.Code, http.StatusBadRequest, recorder.Body.String())
			}
			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
			assertSafeErrorMessage(t, recorder)
		})
	}

	// The rejected queries changed nothing: both committed records come back
	// untouched — content, order and conflict flags included.
	items := listItems(t, router, "/v1/net-policies?namespace=payments")
	if want := []map[string]any{deny, allow}; !reflect.DeepEqual(items, want) {
		t.Fatalf("items after rejected queries = %v, want unchanged %v", items, want)
	}
}

// Legal queries keep the original matching semantics: + means space, %2B/%3B/%26
// are literal +, ; and & inside values rather than separators or illegal input,
// parameters decode exactly once, and the decoded value matches verbatim —
// surrounding spaces and letter case are significant. Legal unknown parameters
// are ignored, and empty segments (including a trailing &) change nothing.
func TestGetNetPoliciesLegalEncodingSemantics(t *testing.T) {
	router, _ := newTestRouter(t)

	spaced := registerCreated(t, router,
		singleRuleBody("pay ments", "spaced", "tier=backend", "ingress", "allow", 80, 80, `{}`), 1, false)
	special := registerCreated(t, router,
		singleRuleBody("payments", "special", "a+b;c&d", "ingress", "allow", 80, 80, `{}`), 2, false)
	plain := registerCreated(t, router,
		singleRuleBody("payments", "plain", "tier=backend", "ingress", "allow", 80, 80, `{}`), 3, false)

	// + decodes to a space.
	items := listItems(t, router, "/v1/net-policies?namespace=pay+ments")
	if len(items) != 1 || !reflect.DeepEqual(items[0], spaced) {
		t.Fatalf("plus-as-space items = %v, want %v", items, spaced)
	}

	// %2B, %3B and %26 are literal characters inside a value, not separators.
	items = listItems(t, router, "/v1/net-policies?label=a%2Bb%3Bc%26d")
	if len(items) != 1 || !reflect.DeepEqual(items[0], special) {
		t.Fatalf("escaped-separator items = %v, want %v", items, special)
	}

	// The escaped & and ; above did not split parameters: intersecting with a
	// namespace condition still works on the decoded value.
	items = listItems(t, router, "/v1/net-policies?namespace=payments&label=a%2Bb%3Bc%26d")
	if len(items) != 1 || !reflect.DeepEqual(items[0], special) {
		t.Fatalf("intersection items = %v, want %v", items, special)
	}

	// Parameters decode exactly once: %252B is the literal text "%2B", not "+".
	miss := doRequest(router, http.MethodGet, "/v1/net-policies?label=a%252Bb%253Bc%2526d", "")
	if miss.Code != http.StatusNotFound {
		t.Fatalf("double-encoded status = %d, want %d", miss.Code, http.StatusNotFound)
	}
	assertErrorCode(t, miss, "NetPolicyNotFoundError")

	// Decoded values match verbatim: no trimming, no case folding.
	for _, target := range []string{
		"/v1/net-policies?namespace=+payments", // leading space is significant
		"/v1/net-policies?namespace=payments+", // trailing space is significant
		"/v1/net-policies?namespace=Payments",  // case is significant
	} {
		recorder := doRequest(router, http.MethodGet, target, "")
		if recorder.Code != http.StatusNotFound {
			t.Fatalf("GET %s status = %d, want %d", target, recorder.Code, http.StatusNotFound)
		}
		assertErrorCode(t, recorder, "NetPolicyNotFoundError")
	}

	// Legal unknown parameters are ignored; empty segments and a trailing &
	// do not change the result.
	want := []map[string]any{special, plain}
	for _, target := range []string{
		"/v1/net-policies?namespace=payments&verbose=true&empty=",
		"/v1/net-policies?namespace=payments&unknown=%2B%3B%26",
		"/v1/net-policies?&namespace=payments&&",
		"/v1/net-policies?namespace=payments&",
	} {
		if items := listItems(t, router, target); !reflect.DeepEqual(items, want) {
			t.Fatalf("GET %s items = %v, want %v", target, items, want)
		}
	}
}

// With the storage layer down a well-formed query reports 503
// storage_unavailable, while a malformed query is still rejected with 400
// before any storage access.
func TestGetNetPoliciesStorageUnavailable(t *testing.T) {
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)
	if err := st.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	recorder := doRequest(router, http.MethodGet, "/v1/net-policies?namespace=payments", "")
	if recorder.Code != http.StatusServiceUnavailable {
		t.Fatalf("legal query status = %d, want %d: %s",
			recorder.Code, http.StatusServiceUnavailable, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "storage_unavailable")
	assertSafeErrorMessage(t, recorder)

	recorder = doRequest(router, http.MethodGet, "/v1/net-policies?namespace=payments&namespace=%ZZ", "")
	if recorder.Code != http.StatusBadRequest {
		t.Fatalf("illegal query status = %d, want %d: %s",
			recorder.Code, http.StatusBadRequest, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
	assertSafeErrorMessage(t, recorder)
}

package api

// String boundary regression tests: identities and labels carrying legal but
// unusual characters (Chinese, supplementary-plane characters, padding spaces,
// single quotes, percent signs, underscores, NUL via JSON escape) must keep
// their verbatim identity through registration, idempotent retry, querying and
// a database reopen, while near-miss strings stay strictly separate. Every
// expectation below is derived from the public contract in README.md, never
// from observed service output.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"unicode/utf16"

	"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
)

// rawBoundaryBody builds a registration body from raw JSON fragments so the
// test controls the exact wire encoding of every string field.
func rawBoundaryBody(nsJSON, nameJSON, labelJSON, rulesJSON, paramsJSON string) string {
	return fmt.Sprintf(`{
		"namespace": %s,
		"name": %s,
		"label": %s,
		"rules": %s,
		"pluginParams": %s
	}`, nsJSON, nameJSON, labelJSON, rulesJSON, paramsJSON)
}

// jsonStringLiteral renders s as a JSON string literal with the standard
// encoder: control characters (including NUL) become \u00XX escapes while
// printable non-ASCII stays as UTF-8.
func jsonStringLiteral(t *testing.T, s string) string {
	t.Helper()
	raw, err := json.Marshal(s)
	if err != nil {
		t.Fatalf("encode %q: %v", s, err)
	}
	return string(raw)
}

// jsonEscapeNonASCII renders s as a JSON string literal with every non-ASCII
// character written as \uXXXX (a surrogate pair beyond the basic plane): a
// different legal wire encoding of the same string.
func jsonEscapeNonASCII(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b.WriteByte('\\')
			b.WriteRune(r)
		case r < 0x20:
			fmt.Fprintf(&b, `\u%04x`, r)
		case r < 0x80:
			b.WriteRune(r)
		case r > 0xFFFF:
			hi, lo := utf16.EncodeRune(r)
			fmt.Fprintf(&b, `\u%04x\u%04x`, hi, lo)
		default:
			fmt.Fprintf(&b, `\u%04x`, r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

// Legal non-blank strings at the boundary — Chinese, supplementary-plane
// characters, leading/trailing spaces, single quotes, percent signs,
// underscores and a NUL written as JSON \u0000 — are stored verbatim as label
// values, returned byte-for-byte on registration, and can be queried back
// exactly through legal percent/plus encoding.
func TestStringBoundarySpecialLabelsRoundTrip(t *testing.T) {
	router, _ := newTestRouter(t)
	rules := `[{"direction": "ingress", "action": "allow", "ports": [80, 80]}]`
	cases := []struct {
		name  string
		label string
	}{
		{"chinese", "华北支付"},
		{"supplementary plane", "扩展𠀀😀"},
		{"padded spaces", "  padded  "},
		{"single quote", "it's"},
		{"percent and underscore", "50%_off"},
		{"nul via json escape", "nul\x00byte"},
	}

	var want []map[string]any
	for i, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			body := rawBoundaryBody(
				`"boundary"`,
				jsonStringLiteral(t, fmt.Sprintf("case-%d", i)),
				jsonStringLiteral(t, tc.label),
				rules, `{}`)
			record := registerCreated(t, router, body, int64(i+1), false)
			want = append(want, record)

			// The legal percent/plus encoding of the exact label finds the
			// record and nothing else.
			items := listItems(t, router, "/v1/net-policies?label="+url.QueryEscape(tc.label))
			if len(items) != 1 || !reflect.DeepEqual(items[0], record) {
				t.Fatalf("GET label=%q items = %v, want exactly %v", tc.label, items, record)
			}
		})
	}

	// The namespace query returns every record, order ascending, fields intact.
	items := listItems(t, router, "/v1/net-policies?namespace=boundary")
	if !reflect.DeepEqual(items, want) {
		t.Fatalf("namespace items = %v, want %v", items, want)
	}
}

// The same legal string written with different JSON encodings (literal UTF-8
// versus \uXXXX escapes, including a surrogate pair and escaped ASCII
// punctuation) is the same content: the first registration returns 201, the
// re-encoded retry returns 200 with the identical record — same submitted
// fields, order and conflict — and consumes neither a record nor an order.
func TestStringBoundaryEquivalentJSONEncodingsAreSameContent(t *testing.T) {
	router, _ := newTestRouter(t)
	deny := `[{"direction": "ingress", "action": "deny", "ports": [80, 100]}]`

	// Identity and label carrying Chinese and a supplementary-plane character.
	literal := rawBoundaryBody(`"华北"`, `"策略𠀀"`, `"tier=后端"`, deny, `{"mode": "enforce"}`)
	seed := registerCreated(t, router, literal, 1, false)

	escaped := rawBoundaryBody(
		jsonEscapeNonASCII("华北"), jsonEscapeNonASCII("策略𠀀"), jsonEscapeNonASCII("tier=后端"),
		deny, `{"mode": "enforce"}`)
	retry := doRequest(router, http.MethodPost, "/v1/net-policies", escaped)
	if retry.Code != http.StatusOK {
		t.Fatalf("escaped retry status = %d, want %d: %s", retry.Code, http.StatusOK, retry.Body.String())
	}
	var retryRecord map[string]any
	if err := json.Unmarshal(retry.Body.Bytes(), &retryRecord); err != nil {
		t.Fatalf("decode retry: %v", err)
	}
	if !reflect.DeepEqual(retryRecord, seed) {
		t.Fatalf("escaped retry record = %v, want identical to %v", retryRecord, seed)
	}

	// Escaped ASCII punctuation: "it's" written with a \u0027 escape and
	// "50%_off" with \u0025 are the same strings as the literal spellings.
	plain := rawBoundaryBody(`"quoted"`, `"it's"`, `"50%_off"`, deny, `{}`)
	seed2 := registerCreated(t, router, plain, 2, false)
	escapedPunct := rawBoundaryBody(`"quoted"`, `"it\u0027s"`, `"50\u0025_off"`, deny, `{}`)
	retry2 := doRequest(router, http.MethodPost, "/v1/net-policies", escapedPunct)
	if retry2.Code != http.StatusOK {
		t.Fatalf("escaped punctuation retry status = %d, want %d: %s", retry2.Code, http.StatusOK, retry2.Body.String())
	}
	var retry2Record map[string]any
	if err := json.Unmarshal(retry2.Body.Bytes(), &retry2Record); err != nil {
		t.Fatalf("decode retry: %v", err)
	}
	if !reflect.DeepEqual(retry2Record, seed2) {
		t.Fatalf("escaped punctuation retry record = %v, want identical to %v", retry2Record, seed2)
	}

	// Neither retry consumed an order: the next brand-new identity takes 3.
	next := rawBoundaryBody(`"华北"`, `"next"`, `"tier=后端"`, deny, `{}`)
	registerCreated(t, router, next, 3, false)

	// Both retries added no record: the namespace holds exactly the seed and
	// the fresh record.
	items := listItems(t, router, "/v1/net-policies?namespace="+url.QueryEscape("华北"))
	if len(items) != 2 || !reflect.DeepEqual(items[0], seed) {
		t.Fatalf("namespace items = %v, want seed plus the fresh record", items)
	}
}

// Identities differing only in letter case, surrounding spaces or Unicode
// combining form are stored as separate records, and namespace/name pairs that
// merely share a separator character are not merged.
func TestStringBoundaryNearIdentitiesStaySeparate(t *testing.T) {
	router, _ := newTestRouter(t)
	rules := `[{"direction": "ingress", "action": "allow", "ports": [80, 80]}]`
	identities := []struct {
		ns, name, label string
	}{
		{"payments", "default-deny", "l-base"},
		{"payments", "Default-Deny", "l-case"},   // case only
		{"payments", "default-deny ", "l-space"}, // trailing space
		{"payments", "café", "l-nfc"},            // NFC composed
		{"payments", "café", "l-nfd"},   // NFD decomposed
		{"a/b", "c", "l-sep-1"},                  // separator inside namespace
		{"a", "b/c", "l-sep-2"},                  // separator inside name
	}
	records := make(map[string]map[string]any, len(identities))
	for i, id := range identities {
		body := rawBoundaryBody(
			jsonStringLiteral(t, id.ns), jsonStringLiteral(t, id.name), jsonStringLiteral(t, id.label),
			rules, `{}`)
		records[id.label] = registerCreated(t, router, body, int64(i+1), false)
	}

	// Each label query returns exactly its own record: the near strings did
	// not collapse onto one another.
	for label, record := range records {
		items := listItems(t, router, "/v1/net-policies?label="+url.QueryEscape(label))
		if len(items) != 1 || !reflect.DeepEqual(items[0], record) {
			t.Fatalf("GET label=%s items = %v, want exactly %v", label, items, record)
		}
	}

	// The separator pairs stay apart on namespace queries.
	items := listItems(t, router, "/v1/net-policies?namespace=a%2Fb")
	if want := []map[string]any{records["l-sep-1"]}; !reflect.DeepEqual(items, want) {
		t.Fatalf("namespace a/b items = %v, want %v", items, want)
	}
	items = listItems(t, router, "/v1/net-policies?namespace=a")
	if want := []map[string]any{records["l-sep-2"]}; !reflect.DeepEqual(items, want) {
		t.Fatalf("namespace a items = %v, want %v", items, want)
	}

	// Unregistered near values miss cleanly: different case, extra space or
	// the other combining form are 404 NetPolicyNotFoundError, never a match.
	for _, target := range []string{
		"/v1/net-policies?namespace=PAYMENTS",
		"/v1/net-policies?namespace=payments+",
		"/v1/net-policies?label=L-BASE",
		"/v1/net-policies?label=+l-base",
		"/v1/net-policies?namespace=a%2Fb+",
	} {
		recorder := doRequest(router, http.MethodGet, target, "")
		if recorder.Code != http.StatusNotFound {
			t.Fatalf("GET %s status = %d, want %d: %s", target, recorder.Code, http.StatusNotFound, recorder.Body.String())
		}
		assertExactErrorShape(t, recorder, "NetPolicyNotFoundError")
	}
}

// Re-posting an existing identity with only the label changed — even by mere
// case or an extra space — is a content conflict: 409 NetPolicyConflictError,
// the original record untouched, and no order consumed.
func TestStringBoundaryLabelOnlyChangeConflicts(t *testing.T) {
	router, _ := newTestRouter(t)
	rules := `[{"direction": "ingress", "action": "allow", "ports": [80, 80]}]`
	seed := registerCreated(t, router,
		rawBoundaryBody(`"payments"`, `"quoted"`, `"50%_off"`, rules, `{}`), 1, false)

	for name, labelJSON := range map[string]string{
		"case changed":    `"50%_OFF"`,
		"trailing space":  `"50%_off "`,
		"combining added": `"50%_off́"`,
	} {
		t.Run(name, func(t *testing.T) {
			changed := rawBoundaryBody(`"payments"`, `"quoted"`, labelJSON, rules, `{}`)
			recorder := doRequest(router, http.MethodPost, "/v1/net-policies", changed)
			if recorder.Code != http.StatusConflict {
				t.Fatalf("status = %d, want %d: %s", recorder.Code, http.StatusConflict, recorder.Body.String())
			}
			assertExactErrorShape(t, recorder, "NetPolicyConflictError")
			assertSafeErrorMessage(t, recorder)
		})
	}

	// The rejections changed nothing and consumed no order.
	items := listItems(t, router, "/v1/net-policies?label=50%25_off")
	if want := []map[string]any{seed}; !reflect.DeepEqual(items, want) {
		t.Fatalf("items after 409 rejections = %v, want unchanged %v", items, want)
	}
	registerCreated(t, router,
		rawBoundaryBody(`"payments"`, `"next"`, `"50%_off"`, rules, `{}`), 2, false)
}

// A rule clash (same direction, opposite action, overlapping ports) flags the
// new record only when namespace and label match verbatim; a label or
// namespace differing by case or a trailing space leaves conflict=false, and
// the earlier records' flags are not rewritten by later commits.
func TestStringBoundaryConflictFlagNeedsExactMatch(t *testing.T) {
	router, _ := newTestRouter(t)
	deny := `[{"direction": "ingress", "action": "deny", "ports": [80, 100]}]`
	allow := `[{"direction": "ingress", "action": "allow", "ports": [100, 200]}]`

	seed := registerCreated(t, router, rawBoundaryBody(`"华北"`, `"seed"`, `"tier=后端"`, deny, `{}`), 1, false)
	// Exact namespace and label: the opposite-action overlap is flagged.
	clash := registerCreated(t, router, rawBoundaryBody(`"华北"`, `"clash"`, `"tier=后端"`, allow, `{}`), 2, true)
	// Same clashing rule but label or namespace off by case/space: not flagged.
	caseLabel := registerCreated(t, router, rawBoundaryBody(`"华北"`, `"case-label"`, `"Tier=后端"`, allow, `{}`), 3, false)
	spacedLabel := registerCreated(t, router, rawBoundaryBody(`"华北"`, `"spaced-label"`, `"tier=后端 "`, allow, `{}`), 4, false)
	spacedNs := registerCreated(t, router, rawBoundaryBody(`"华北 "`, `"spaced-ns"`, `"tier=后端"`, allow, `{}`), 5, false)

	// Every record committed in namespace 华北 keeps its original flag.
	items := listItems(t, router, "/v1/net-policies?namespace="+url.QueryEscape("华北"))
	if want := []map[string]any{seed, clash, caseLabel, spacedLabel}; !reflect.DeepEqual(items, want) {
		t.Fatalf("items = %v, want %v (earlier conflict flags unchanged)", items, want)
	}
	items = listItems(t, router, "/v1/net-policies?namespace="+url.QueryEscape("华北 "))
	if want := []map[string]any{spacedNs}; !reflect.DeepEqual(items, want) {
		t.Fatalf("spaced namespace items = %v, want %v", items, want)
	}
}

// Query decoding is exact and single-pass: + and %20 both mean space, a
// literal + or % in a stored value needs its escape, escapes decode once, and
// % and _ are ordinary characters rather than wildcards. Namespace and label
// together intersect, and items come back order-ascending with every field.
func TestStringBoundaryQueryEncodingSemantics(t *testing.T) {
	router, _ := newTestRouter(t)
	rules := `[{"direction": "ingress", "action": "allow", "ports": [80, 80]}]`

	spaced := registerCreated(t, router, rawBoundaryBody(`"pay ments"`, `"a"`, `"spaced"`, rules, `{}`), 1, false)
	plus := registerCreated(t, router, rawBoundaryBody(`"literal"`, `"plus"`, `"a+b"`, rules, `{}`), 2, false)
	percent := registerCreated(t, router, rawBoundaryBody(`"literal"`, `"percent"`, `"a%b"`, rules, `{}`), 3, false)
	under := registerCreated(t, router, rawBoundaryBody(`"literal"`, `"under"`, `"a_b"`, rules, `{}`), 4, false)
	plain := registerCreated(t, router, rawBoundaryBody(`"literal"`, `"plain"`, `"axb"`, rules, `{}`), 5, false)
	encoded := registerCreated(t, router, rawBoundaryBody(`"literal"`, `"encoded"`, `"a%2Bb"`, rules, `{}`), 6, false)

	// A stored space is found by + and by %20 alike.
	for _, target := range []string{
		"/v1/net-policies?namespace=pay+ments",
		"/v1/net-policies?namespace=pay%20ments",
	} {
		items := listItems(t, router, target)
		if want := []map[string]any{spaced}; !reflect.DeepEqual(items, want) {
			t.Fatalf("GET %s items = %v, want %v", target, items, want)
		}
	}

	// A literal + in the stored label needs %2B; a raw + decodes to a space
	// and misses.
	items := listItems(t, router, "/v1/net-policies?label=a%2Bb")
	if want := []map[string]any{plus}; !reflect.DeepEqual(items, want) {
		t.Fatalf("label a%%2Bb items = %v, want %v", items, want)
	}
	recorder := doRequest(router, http.MethodGet, "/v1/net-policies?label=a+b", "")
	if recorder.Code != http.StatusNotFound {
		t.Fatalf("label a+b status = %d, want %d (raw + decodes to a space)", recorder.Code, http.StatusNotFound)
	}
	assertExactErrorShape(t, recorder, "NetPolicyNotFoundError")

	// % and _ are literal characters, not wildcards: each matches only its own
	// record, never the "axb" record.
	items = listItems(t, router, "/v1/net-policies?label=a%25b")
	if want := []map[string]any{percent}; !reflect.DeepEqual(items, want) {
		t.Fatalf("label a%%25b items = %v, want %v (%% must not act as a wildcard)", items, want)
	}
	items = listItems(t, router, "/v1/net-policies?label=a_b")
	if want := []map[string]any{under}; !reflect.DeepEqual(items, want) {
		t.Fatalf("label a_b items = %v, want %v (_ must not act as a wildcard)", items, want)
	}

	// Escapes decode exactly once: %252B is the literal text "%2B" and finds
	// the record storing that text, not the "a+b" record.
	items = listItems(t, router, "/v1/net-policies?label=a%252Bb")
	if want := []map[string]any{encoded}; !reflect.DeepEqual(items, want) {
		t.Fatalf("label a%%252Bb items = %v, want %v (parameters decode once)", items, want)
	}

	// Namespace and label together intersect.
	items = listItems(t, router, "/v1/net-policies?namespace=literal&label=a%2Bb")
	if want := []map[string]any{plus}; !reflect.DeepEqual(items, want) {
		t.Fatalf("intersection items = %v, want %v", items, want)
	}

	// Unregistered near values miss: decoded space, wrong case, extra space.
	for _, target := range []string{
		"/v1/net-policies?label=a%20b",
		"/v1/net-policies?namespace=Literal",
		"/v1/net-policies?label=a%2Bb+",
	} {
		recorder := doRequest(router, http.MethodGet, target, "")
		if recorder.Code != http.StatusNotFound {
			t.Fatalf("GET %s status = %d, want %d", target, recorder.Code, http.StatusNotFound)
		}
		assertExactErrorShape(t, recorder, "NetPolicyNotFoundError")
	}

	// The full namespace listing comes back order-ascending, fields complete.
	items = listItems(t, router, "/v1/net-policies?namespace=literal")
	if want := []map[string]any{plus, percent, under, plain, encoded}; !reflect.DeepEqual(items, want) {
		t.Fatalf("namespace items = %v, want %v", items, want)
	}
}

// A query carrying an incomplete or non-hex percent escape is rejected as 400
// InvalidNetPolicyInputError even when another condition would have matched a
// committed record: no partial hit leaks, and the registry is untouched.
func TestStringBoundaryMalformedQueryLeaksNothing(t *testing.T) {
	router, _ := newTestRouter(t)
	rules := `[{"direction": "ingress", "action": "allow", "ports": [80, 80]}]`
	seed := registerCreated(t, router,
		rawBoundaryBody(`"boundary"`, `"rec"`, `"50%_off"`, rules, `{}`), 1, false)

	cases := map[string]string{
		"incomplete escape at value end":     "/v1/net-policies?label=50%",
		"incomplete escape mid value":        "/v1/net-policies?label=50%2",
		"non-hex escape in value":            "/v1/net-policies?namespace=boundar%GG",
		"lone percent in name":               "/v1/net-policies?lab%el=x",
		"bad escape after matching label":    "/v1/net-policies?label=50%25_off&junk=%2",
		"bad escape before matching label":   "/v1/net-policies?junk=%&label=50%25_off",
		"bad escape with non-matching value": "/v1/net-policies?label=missing&junk=%XY",
	}
	for name, target := range cases {
		t.Run(name, func(t *testing.T) {
			recorder := doRequest(router, http.MethodGet, target, "")
			if recorder.Code != http.StatusBadRequest {
				t.Fatalf("GET %s status = %d, want %d: %s",
					target, recorder.Code, http.StatusBadRequest, recorder.Body.String())
			}
			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
			assertSafeErrorMessage(t, recorder)
		})
	}

	// The rejected queries leaked nothing and changed nothing: the record is
	// still returned exactly, and the next identity takes the next order.
	items := listItems(t, router, "/v1/net-policies?label=50%25_off")
	if want := []map[string]any{seed}; !reflect.DeepEqual(items, want) {
		t.Fatalf("items after rejected queries = %v, want unchanged %v", items, want)
	}
	registerCreated(t, router,
		rawBoundaryBody(`"boundary"`, `"next"`, `"50%_off"`, rules, `{}`), 2, false)
}

// Special-string records survive a close/reopen of the same database file:
// the same encoded queries return the original records, an idempotent retry
// in a different JSON encoding still returns 200 with the stored record (the
// old conflict flag is not recomputed), a changed label is still 409, and the
// next new identity continues at max order + 1.
func TestStringBoundarySurvivesReopen(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "service.db")
	st, err := store.Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)

	deny := `[{"direction": "ingress", "action": "deny", "ports": [80, 100]}]`
	allow := `[{"direction": "ingress", "action": "allow", "ports": [100, 200]}]`
	nulLabel := jsonStringLiteral(t, "nul\x00byte")

	seed := registerCreated(t, router,
		rawBoundaryBody(`"华北"`, `"deny"`, nulLabel, deny, `{"mode": "enforce"}`), 1, false)
	sup := registerCreated(t, router,
		rawBoundaryBody(`"华北"`, `"sup"`, `"扩展𠀀😀"`, deny, `{}`), 2, false)
	clash := registerCreated(t, router,
		rawBoundaryBody(`"华北"`, `"clash"`, nulLabel, allow, `{}`), 3, true)

	if err := st.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	reopened, err := store.Open(dbPath)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	t.Cleanup(func() { reopened.Close() })
	router = NewRouter(reopened)

	// The same encoded queries return the original records, order ascending.
	items := listItems(t, router, "/v1/net-policies?namespace="+url.QueryEscape("华北"))
	if want := []map[string]any{seed, sup, clash}; !reflect.DeepEqual(items, want) {
		t.Fatalf("namespace items after reopen = %v, want %v", items, want)
	}
	items = listItems(t, router, "/v1/net-policies?label="+url.QueryEscape("nul\x00byte"))
	if want := []map[string]any{seed, clash}; !reflect.DeepEqual(items, want) {
		t.Fatalf("nul label items after reopen = %v, want %v", items, want)
	}

	// Idempotent retry in the escaped encoding: 200 with the stored record,
	// conflict flag not recomputed even though the clashing record exists.
	retry := doRequest(router, http.MethodPost, "/v1/net-policies",
		rawBoundaryBody(jsonEscapeNonASCII("华北"), `"deny"`, nulLabel, deny, `{"mode": "enforce"}`))
	if retry.Code != http.StatusOK {
		t.Fatalf("retry after reopen status = %d, want %d: %s", retry.Code, http.StatusOK, retry.Body.String())
	}
	var retryRecord map[string]any
	if err := json.Unmarshal(retry.Body.Bytes(), &retryRecord); err != nil {
		t.Fatalf("decode retry: %v", err)
	}
	if !reflect.DeepEqual(retryRecord, seed) {
		t.Fatalf("retry after reopen = %v, want the original %v", retryRecord, seed)
	}

	// A changed label on the same identity is still 409 after the reopen.
	changed := doRequest(router, http.MethodPost, "/v1/net-policies",
		rawBoundaryBody(`"华北"`, `"deny"`, `"changed"`, deny, `{"mode": "enforce"}`))
	if changed.Code != http.StatusConflict {
		t.Fatalf("changed label status = %d, want %d: %s", changed.Code, http.StatusConflict, changed.Body.String())
	}
	assertExactErrorShape(t, changed, "NetPolicyConflictError")

	// Neither the retry nor the 409 consumed an order.
	registerCreated(t, router,
		rawBoundaryBody(`"华北"`, `"after-reopen"`, `"tier=后端"`, deny, `{}`), 4, false)
}

